import {installVoice} from './voice-local.js';
import {velocity,acceleration,position,motion,grade,KEY,initial,valid,viewpoints,makeAnswer} from './model.js';
const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang=new URLSearchParams(location.search).get('lang')==='zh'?'zh':'en',s=initial(),blocked=false,storageIssue=false,lastRaw=null,ephemeral={direction:'',speed:''};
try{lastRaw=localStorage.getItem(KEY);if(lastRaw){const parsed=JSON.parse(lastRaw);if(!valid(parsed))throw Error();s=parsed;}}catch{blocked=true;storageIssue=true;}
const L=(zh,en)=>lang==='zh'?zh:en;
function status(){ $('saveStatus').textContent=blocked?L('本機紀錄有衝突或無法讀取；目前只保留於本頁，請先下載筆記。','Local record unavailable or changed elsewhere. Download notes before leaving.'):storageIssue?L('無法儲存；請在離開前下載筆記。','Could not save. Download notes before leaving.'):L('已保存在這個瀏覽器','Saved in this browser');$('saveStatus').classList.toggle('error',blocked||storageIssue);}
function save(){if(!blocked)try{const current=localStorage.getItem(KEY);if(current!==lastRaw){blocked=true;}else{const raw=JSON.stringify(s);localStorage.setItem(KEY,raw);lastRaw=raw;storageIssue=false;}}catch{storageIssue=true;}status();}
window.addEventListener('storage',e=>{if(e.key===KEY||e.key===null){blocked=true;status();}});
const claimLabel=c=>({custom:L('我想提出自己的說法。','I have my own version.'),yes:L('加速度為正，就一定往前走。','Positive acceleration always means moving forward.'),no:L('不一定，還要看速度。','Not necessarily; velocity also matters.'),unsure:L('我還不確定，想先試試。','I’m not sure yet. I’d like to test it.')}[c]||'');
function bubble(text){return `<div class="bubble"><span class="speaker">Q / QUIDENCE</span><p>${text}</p></div>`;}
function quote(text){return `<div class="quote">${esc(text)}</div>`;}
function button(id,text,cls='primary'){return `<button id="${id}" class="${cls}">${text}</button>`;}
function field(id,label,value='',placeholder=''){return `<label class="field" for="${id}">${label}</label><textarea id="${id}" maxlength="2000" placeholder="${esc(placeholder)}">${esc(value)}</textarea>`;}
function bindText(id,key){$(id).addEventListener('input',e=>{s[key]=e.target.value;save();});}
function advance(n){s.stage=n;ephemeral={direction:'',speed:''};save();render();$('conversationTitle').scrollIntoView({behavior:'auto',block:'start'});}
function translation(){document.documentElement.lang=lang==='zh'?'zh-Hant':'en';document.querySelectorAll('[data-zh]').forEach(e=>{e.innerHTML=e.dataset[lang];});$('language').textContent=lang==='zh'?'English':'中文（繁體）';}
function graph(){const transfer=s.stage===3,t=s.t, X=t=>55+t*100,Y=v=>260-v*23;let path='';for(let i=0;i<=100;i++){const x=i/20,v=transfer?4-x:velocity(x);path+=`${i?'L':'M'}${X(x)},${Y(v)} `;}let content=`<title id="graphTitle">${L('速度與時間','Velocity over time')}</title><desc id="graphDescription">${esc(L('橫軸時間 0 至 5 分鐘；縱軸速度，單位 m/s。','Time from 0 to 5 minutes; velocity in m/s.'))}</desc>`;
for(let v=-2;v<=8;v+=2)content+=`<line x1="55" x2="555" y1="${Y(v)}" y2="${Y(v)}" stroke="${v===0?'#899d9d':'#e8edec'}" ${v===0?'':'stroke-dasharray="3 5"'}/><text x="42" y="${Y(v)+4}" text-anchor="end" font-size="11" fill="#617578">${v}</text>`;
for(let i=0;i<=5;i++)content+=`<text x="${X(i)}" y="316" text-anchor="middle" font-size="11" fill="#617578">${i}</text>`;
const m=motion(t,transfer);content+=`<text x="55" y="18" font-size="11" fill="#617578">v (m/s)</text><text x="580" y="284" text-anchor="end" font-size="11" fill="#617578">t (min)</text><path d="${path}" fill="none" stroke="#153f44" stroke-width="3.5"/><line x1="${X(t)}" x2="${X(t)}" y1="32" y2="300" stroke="#dc795e" stroke-dasharray="4 5"/><circle cx="${X(t)}" cy="${Y(m.v)}" r="8" fill="#dc795e" stroke="white" stroke-width="3"/>`;
$('graph').innerHTML=content;$('time').value=t;$('timeOut').textContent=`${t.toFixed(2)} min`;$('velocity').textContent=m.v.toFixed(2);$('acceleration').textContent=m.a.toFixed(4);$('modelName').textContent=transfer?'02 / TRANSFER':'01 / RIDE';$('modelDesc').textContent=transfer?L('新的騎行：v(t) = 4 − t，0 ≤ t ≤ 5。','A new ride: v(t) = 4 − t, 0 ≤ t ≤ 5.'):L('速度模型：v(t) = (t − 2)(t − 4)，0 ≤ t ≤ 5。','Velocity model: v(t) = (t − 2)(t − 4), 0 ≤ t ≤ 5.');
const p=transfer?60*(4*t-t*t/2):position(t),px=55+p/500*500;$('track').innerHTML=`<line x1="55" x2="555" y1="24" y2="24" stroke="#c9d8d3" stroke-width="3"/><circle cx="${px}" cy="24" r="10" fill="#153f44"/><text x="55" y="55" font-size="12" fill="#617578">0 m</text><text x="555" y="55" text-anchor="end" font-size="12" fill="#617578">500 m</text>`;$('trackNote').textContent=L(`從起點的位置：${p.toFixed(1)} m。點表示位置，不表示方向。`,`Position from the start: ${p.toFixed(1)} m. The dot shows position, not direction.`);$('capture').disabled=transfer||s.samples.length>=20;$('capture').textContent=transfer?L('遷移題使用新模型；原證據保留在下方','New model for transfer; original evidence stays below'):s.samples.length>=20?L('已保留 20 個時刻','20 moments saved'):L('＋ 留下這個時刻作為證據','＋ Keep this moment as evidence');
}
function samples(){ $('samples').innerHTML=s.samples.map((x,i)=>`<div class="sample"><button data-sample="${i}">${x.t.toFixed(2)} min</button> · v = ${velocity(x.t).toFixed(2)} m/s · a = ${acceleration(x.t).toFixed(4)} m/s² <label class="field" for="note${i}">${L('這個時刻告訴你什麼？（可選）','What does this moment show? (optional)')}</label><textarea id="note${i}" maxlength="2000">${esc(x.note)}</textarea></div>`).join('');s.samples.forEach((x,i)=>{$(`note${i}`).oninput=e=>{x.note=e.target.value;save();};});document.querySelectorAll('[data-sample]').forEach(b=>{b.disabled=s.stage===3;b.onclick=()=>{s.t=s.samples[+b.dataset.sample].t;save();graph();};});}
function evidenceAt(t){const m=motion(t);return `<div class="evidence"><p>${L('你選的證據','Your selected evidence')}: t = ${t.toFixed(2)} min</p><p>v = ${m.v.toFixed(2)} m/s · a = ${m.a.toFixed(4)} m/s²</p></div>`;}
function correction(){return `<details><summary class="quiet">${L('這不是我的意思／補充說明','That’s not what I meant / add context')}</summary>${field('correction',L('請補充；你的原話會一起保留，不自動判分。','Add context. Both versions are kept, without automatic grading.'),s.correction)}</details>`;}
function checkForm(kind){const a=s[kind],pick=a?.mode==='custom'?'custom':a?.pick||s[kind+'Pick']||'';return `<p class="invitation">${L('這裡有三個說法，但不保證其中有合適答案。你可以選一個並補充理由，也可以直接寫自己的版本。','Here are three viewpoints. None may fit. Choose one and explain why, or write your own version.')}</p><div class="choices" role="group" aria-label="${L('三個說法','Three viewpoints')}">${viewpoints[kind].map((p,i)=>`<button class="choice ${pick===p.id?'selected':''}" data-view="${p.id}" aria-pressed="${pick===p.id}" ${a?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(p[lang])}</span></button>`).join('')}</div><div class="own-answer ${pick==='custom'?'selected':''}"><button id="ownAnswer" class="own-toggle" aria-pressed="${pick==='custom'}" ${a?'disabled':''}>${L('✎ 我想提出自己的說法','✎ I have my own version')}</button>${field('reason',pick==='custom'?L('我的答案與理由','My answer and reasoning'):L('為什麼這樣想？也可以說說選項哪裡不夠完整。（可選）','Why do you think so? You can also say what the option leaves out. (optional)'),a?a.reason:s[kind+'Draft'],pick==='custom'?L('例如：我認為……，因為圖上……','I think… because on the graph…'):L('把選項當成思考的起點，用自己的話補充。','Use the option as a starting point, then add your own thinking.'))}</div><p class="not-scored">${L('自寫答案不會因為沒有選 A、B、C 就被判錯。原型只核對預設說法中的數學結論，文字理由保留待討論。','Writing your own answer is not marked wrong. This prototype checks only the numerical claims in preset viewpoints; your wording is kept for discussion.')}</p><div class="actions">${button('check',L('帶著我的想法繼續','Continue with my thinking'))}${button('hint',L('給我一點提示','A small hint'),'quiet')}</div><div id="hintArea">${s.hints.includes(kind)?hintText(kind):''}</div><div id="answerFeedback">${a?feedback(kind,a):''}</div>`;}
function hintText(kind){return `<div class="hint">${L('方向看速度的正負；速率是 |v|。觀察速度正在靠近零，還是離零更遠。','Direction follows the sign of velocity; speed is |v|. Is velocity moving toward zero or farther away?')}</div>`;}
function answerName(a){if(a.mode==='custom')return L('我自己的說法（不自動判分）','My own version (not automatically graded)');const dir={forward:L('往前','forward'),backward:L('往後','backward'),still:L('瞬間靜止','instantly at rest'),unsure:L('不確定','unsure')},speed={faster:L('變快','speed increasing'),slower:L('變慢','speed decreasing'),instant:L('瞬間變化率為零','zero instantaneous rate'),unsure:L('不確定','unsure')};return `${dir[a.direction]} / ${speed[a.speed]}`;}
function feedback(kind,a){const tr=kind==='transfer',g=grade(a,tr?3:3.5,tr),own=a.mode==='custom';return `<div class="evidence ${!own&&(!g.direction||!g.speed)?'warning':''}"><p>${L('你留下的想法','Your recorded thinking')}: ${answerName(a)}</p>${own?`<p>${L('你的原話已保留。這段答案不自動判分；我們先找圖上的證據。','Your words are preserved. This answer is not automatically graded; let’s look for evidence on the graph.')}</p>${quote(a.reason)}`:`<p>${L('方向','Direction')}: ${g.direction?L('與模型一致','matches the model'):L('仍需核對','needs another look')} · ${L('速率變化','Speed change')}: ${g.speed?L('與模型一致','matches the model'):L('仍需核對','needs another look')}</p>`}<p>${a.hinted?L('作答前已看過提示。','A hint was viewed before this answer.'):L('作答前未開啟本題提示。','No hint for this question was opened before this answer.')}</p></div>${bubble(own?L('圖上的哪個位置或哪一段變化，最能支持你剛才寫的說法？你可以移動滑桿，再補充一句。','Which point or change on the graph best supports what you just wrote? Move the slider, then add a sentence.'):g.direction&&g.speed?L('這個說法的方向與速率變化都符合模型。你會用圖上的哪個線索，向選了另一個說法的人解釋？','The direction and speed change match the model. Which clue on the graph would you use to explain it to someone who chose differently?'):L('我們不必硬選原來的說法。試著保留你認為合理的部分，再改寫需要調整的部分。你會怎麼說？','You do not have to keep the original wording. Keep the part you find reasonable and rewrite what needs changing. How would you put it?'))}${field('revision',L('補充、改寫，或留下疑問（可選；原回答仍保留）','Add evidence, revise, or leave a question (optional; your first answer stays)'),s[kind+'Revision']||'')}<details id="worked"><summary class="quiet">${L('我想看這一步的解釋','Show me an explanation')}</summary><p class="hint">${tr?L('t = 3 時，v = 1 > 0，車往前走；a = −1/60 < 0，速度正在靠近零，因此速率變小。這三個預設說法都不完全成立，你可以提出「向前走，但正在慢下來」。','At t = 3, v = 1 > 0: forward. a = −1/60 < 0: velocity approaches zero, so speed decreases. None of the three preset viewpoints is fully correct. A better version is “moving forward, but slowing down.”'):L('t = 3.5 時，v = −0.75 < 0，車往後走；a = 1/60 > 0，速度正在靠近零，因此速率變小。正加速度不保證向前。','At t = 3.5, v = −0.75 < 0: backward. a = 1/60 > 0: velocity approaches zero, so speed decreases. Positive acceleration does not guarantee forward motion.')}</p></details><div class="actions">${button('next',tr?L('整理我的探索','See my field notes'):L('換一段新圖試試','Try a new graph'))}</div>`;}
function bindCheck(kind){const a=s[kind];let pick=s[kind+'Pick']||'';const update=()=>{$('check').disabled=!!a||!pick||(pick==='custom'&&!s[kind+'Draft'].trim());};$('reason').disabled=!!a;$('reason').oninput=e=>{s[kind+'Draft']=e.target.value;save();update();};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{s[kind+'Pick']=b.dataset.view;save();render();});$('ownAnswer').onclick=()=>{s[kind+'Pick']='custom';save();render();$('reason').focus();};update();$('hint').onclick=()=>{if(!s.hints.includes(kind))s.hints.push(kind);save();$('hintArea').innerHTML=hintText(kind);};$('check').onclick=()=>{s[kind]=makeAnswer(kind,pick,s[kind+'Draft'],s.hints.includes(kind));save();render();};if(a){bindText('revision',kind+'Revision');$('next').onclick=()=>{if(kind==='challenge'){s.t=3;advance(3);}else advance(4);};$('worked').ontoggle=e=>{if(e.target.open&&!s.hints.includes(kind)){s.hints.push(kind);save();}};}}
function render(){voice.cancelReview();translation();const labels=[L('說出想法','Your idea'),L('尋找證據','Find evidence'),L('檢驗判斷','Test the claim'),L('換個情境','Try a new case'),L('回看思考','Reflect')];$('progress').innerHTML=labels.map((t,i)=>`<div class="step ${s.stage===i?'active':s.stage>i?'done':''}" ${s.stage===i?'aria-current="step"':''}><b>${s.stage>i?'✓':String(i+1).padStart(2,'0')}</b>${t}</div>`).join('');$('conversationTitle').textContent=labels[s.stage];let html='';
if(s.stage===0){html=bubble(L('有人說：「加速度是正的，所以車一定在往前走。」你怎麼看？','Someone says: “Acceleration is positive, so the rider must be moving forward.” What do you think?'))+`<div class="choices">${['yes','no','unsure'].map(c=>`<button class="choice ${s.claim===c?'selected':''}" data-claim="${c}" aria-pressed="${s.claim===c}">${claimLabel(c)}</button>`).join('')}</div>`+`<div class="own-answer ${s.claim==='custom'?'selected':''}">${button('initialOwn',L('✎ 我想提出自己的說法','✎ I have my own version'),'own-toggle')}${field('draft',s.claim==='custom'?L('我的答案與理由','My answer and reasoning'):L('說說你的理由（可選）','Tell me why (optional)'),s.draft,L('可以先說不確定的地方，不必寫成標準答案。','It’s fine to say what you’re unsure about.'))}</div>`+`<p class="small">${L('可以選一項並補充理由，也可以切換為自己的說法。系統不會從文字猜測你的立場。','Choose a view and explain, or switch to your own version. The prototype will not guess your stance from your wording.')}</p><div class="actions">${button('begin',L('用圖來試試','Let’s test it on the graph'))}</div>`;}
if(s.stage===1){html=`<span class="mini-label">${L('你確認的想法','YOUR CONFIRMED VIEW')}</span>${quote(claimLabel(s.claim))}${s.original?quote(s.original):''}`+bubble(s.claim==='yes'?L('你認為正加速度代表向前。請在圖上選一個你認為支持這個判斷的時刻，再留下它。','You think positive acceleration means moving forward. Choose a moment you think supports that idea, and keep it as evidence.'):s.claim==='no'?L('你認為還要看速度。試著找一個「加速度為正、卻沒有往前」的時刻。','You think velocity matters too. Look for a moment with positive acceleration but no forward motion.'):L('我們先觀察。選一個你感興趣的時刻，看看速度與加速度的正負。','Let’s observe first. Choose a moment that interests you and compare the signs of velocity and acceleration.'))+`<p class="small">${L('移動左側滑桿（手機在上方），再按「留下這個時刻」。','Move the graph slider (above on mobile), then keep the moment.')}</p><div id="selectedEvidence">${s.samples.length?evidenceAt(s.samples.at(-1).t):''}</div>${correction()}<div class="actions">${button('probe',L('帶著這個證據繼續','Continue with this evidence'))}</div>`;}
if(s.stage===2){const x=s.samples.at(-1),m=motion(x.t);let follow=x.t>3&&x.t<4?L('你找到了一個正加速度、負速度的時刻。接著固定看 t = 3.5 分鐘，把方向與速率變化分開判斷。','You found positive acceleration with negative velocity. Now focus on t = 3.5 minutes and separate direction from speed change.'):m.a>0&&m.v>0?L('這個時刻確實同時有正速度與正加速度。但一個符合的例子，還不能確認「一定」。我們再看 t = 3.5 分鐘。','Your moment has both positive velocity and positive acceleration. One supporting example cannot establish “always.” Let’s also look at t = 3.5 minutes.'):L('這個時刻值得保留。為了直接檢驗「正加速度就往前」，我們再看 t = 3.5 分鐘。','Keep this observation. To test “positive acceleration means forward,” let’s also examine t = 3.5 minutes.');html=evidenceAt(x.t)+bubble(follow)+`<div class="actions">${button('focus',L('圖上定位到 3.5 分鐘','Focus graph at 3.5 min'),'secondary')}</div><p class="prompt">${L('只針對 t = 3.5 分鐘：你怎麼描述車的運動？','At t = 3.5 minutes specifically, how would you describe the motion?')}</p>`+checkForm('challenge');}
if(s.stage===3){html=bubble(L('換一段新的騎行：v(t) = 4 − t。請看 t = 3 分鐘，這次你會怎麼判斷？','A fresh ride: v(t) = 4 − t. At t = 3 minutes, how would you describe the motion?'))+`<div class="actions">${button('focus',L('圖上定位到 3 分鐘','Focus graph at 3 min'),'secondary')}</div><p class="small">${L('這是一題新的近似遷移檢查；前一題的學習與提示仍屬於整段探索的一部分。','This is a new, near-transfer check. Learning and help from the previous question remain part of the session.')}</p>`+checkForm('transfer');}
if(s.stage===4){const g=grade(s.transfer,3,true);html=bubble(L('這次探索留下了幾個可以回看的證據。你不需要把最初的想法藏起來。','You’ve left a trail of evidence. There is no need to hide your first idea.'))+`<div class="summary-row"><h3>${L('01 / 你最初怎麼想','01 / Where you started')}</h3>${quote(claimLabel(s.claim))}${s.original?quote(s.original):''}${s.correction?quote(s.correction):''}</div><div class="summary-row"><h3>${L('02 / 你實際做了什麼','02 / What you actually tested')}</h3><p>${L(`你保留了 ${s.samples.length} 個時刻，並檢查了 t = 3.5 的方向與速率。`,`You kept ${s.samples.length} ${s.samples.length===1?'moment':'moments'} and checked direction and speed at t = 3.5.`)}</p><p>${L('第一次選答','First choice')}: ${answerName(s.challenge)} · ${s.challenge.hinted?L('作答前看過本題提示','hint viewed before answering'):L('作答前未看本題提示','no question hint before answering')}</p>${s.challenge.reason?quote(s.challenge.reason):''}${s.challengeRevision?`<p class="mini-label">${L('後來的補充／改寫','LATER ADDITION / REVISION')}</p>${quote(s.challengeRevision)}`:''}</div><div class="summary-row"><h3>${L('03 / 新情境提供的證據','03 / Evidence from a new case')}</h3><p>${L('第一次選答','First choice')}: ${answerName(s.transfer)}</p><p>${s.transfer.mode==='custom'?L('你用自己的說法回應了新情境。文字不自動判分，仍需核對理由與圖上的證據。','You responded to the new case in your own words. That text is not automatically graded; the reasoning still needs to be checked against the graph.'):g.direction&&g.speed?L('新情境中，方向與速率變化的選答都與模型一致。','In the new case, both direction and speed-change choices match the model.'):L('新情境中，仍有選答需要核對；可以回看圖形，再比較速度的正負與離零的遠近。','Some choices in the new case need another look. Compare the sign of velocity and its distance from zero.')}</p><p>${s.transfer.hinted?L('本題作答前看過提示。','A hint was viewed before this answer.'):L('本題作答前未開啟提示；前一題仍可能提供了幫助。','No hint was opened before this answer; the previous question may still have helped.')}</p>${s.transfer.reason?quote(s.transfer.reason):''}${s.transferRevision?`<p class="mini-label">${L('後來的補充／改寫','LATER ADDITION / REVISION')}</p>${quote(s.transferRevision)}`:''}</div><div class="summary-row"><h3>${L('04 / 我們還不能下的結論','04 / What this does not yet establish')}</h3><p>${L('這些選答不足以證明整個概念已掌握。這仍需更多情境的證據；接下來可試一張不顯示數值的圖，自己找出「向後但變快」的一段並解釋。','These choices do not establish mastery of the whole concept. More examples are needed to check understanding. Next, try a graph without numerical readouts: find an interval of backward motion with increasing speed and explain it.')}</p></div>${field('reflection',L('現在你想怎麼說？也可以留下新的疑問。','How would you put it now? You can leave a new question too.'),s.reflection)}<p class="small">${L('這是你的反思，不會被改寫成系統替你下的結論。','This is your reflection, not a conclusion rewritten on your behalf.')}</p><div class="actions">${button('download',L('帶走我的探索筆記','Take my field notes'))}${button('revisit',L('再看新情境的圖','Revisit the new graph'),'secondary')}</div>`;}
$('dialogue').innerHTML=html;
if(s.stage===0){$('draft').oninput=e=>{s.draft=e.target.value;save();$('begin').disabled=!s.claim||(s.claim==='custom'&&!s.draft.trim());};$('initialOwn').onclick=()=>{s.claim='custom';save();render();$('draft').focus();};document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{s.claim=b.dataset.claim;save();render();});$('begin').disabled=!s.claim||(s.claim==='custom'&&!s.draft.trim());$('begin').onclick=()=>{s.original=s.draft;advance(1);};}
if(s.stage===1){bindText('correction','correction');$('probe').disabled=!s.samples.length;$('probe').onclick=()=>{s.t=3.5;advance(2);};}
if(s.stage===2||s.stage===3){const kind=s.stage===2?'challenge':'transfer';bindCheck(kind);$('focus').onclick=()=>{s.t=s.stage===2?3.5:3;save();graph();};}
if(s.stage===4){bindText('reflection','reflection');$('download').onclick=download;$('revisit').onclick=()=>{s.t=3;advance(3);};}
voice.attach();
if((s.stage===2||s.stage===3)){const kind=s.stage===2?'challenge':'transfer';if(s[kind])$('revision').previousElementSibling.before(voice.reviewBox({kind,answer:s[kind],revision:()=>s[kind+'Revision']||'',saved:s.aiReviews?.[kind]}));}
graph();samples();status();}
$('time').addEventListener('input',e=>{s.t=+e.target.value;graph();save();});$('graph').addEventListener('click',e=>{const svg=$('graph'),point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const p=point.matrixTransform(svg.getScreenCTM().inverse());s.t=Math.max(0,Math.min(5,Math.round((p.x-55)/100*20)/20));graph();save();});
$('capture').onclick=()=>{if(s.stage===3||s.samples.length>=20)return;s.samples.push({t:s.t,note:''});save();render();};
$('language').onclick=()=>{lang=lang==='zh'?'en':'zh';const u=new URL(location);u.searchParams.set('lang',lang);history.replaceState(null,'',u);render();};
function download(){const lines=['# Quidence · Think in Motion',L('引導式對話原型；文字解釋不自動評分。','Guided dialogue prototype. Written explanations are not automatically graded.'),'',`Stage: ${s.stage+1}/5`,L('## 最初判斷','## Initial view'),claimLabel(s.claim),s.original||s.draft,L('## 補充說明','## Clarification'),s.correction,L('## 原模型與證據','## Original model and evidence'),'v(t)=(t−2)(t−4) m/s; t in minutes; a(t)=(2t−6)/60 m/s².',...s.samples.map(x=>`t=${x.t} min; v=${velocity(x.t)} m/s; a=${acceleration(x.t)} m/s²\n${x.note}`)];for(const k of ['challenge','transfer']){lines.push(`## ${k==='challenge'?'t=3.5, original model':'t=3, new model v(t)=4−t'}`);if(s[k]){lines.push(answerName(s[k]),s[k].reason,L('後來的補充／改寫：','Later addition / revision:'),s[k+'Revision']||'',`Hint before answer: ${s[k].hinted}`,s[k].mode==='custom'?L('自寫答案：不自動判分。','Own response: not automatically graded.'):`Numerical claims: direction ${grade(s[k],k==='challenge'?3.5:3,k==='transfer').direction?'matches':'needs review'}; speed ${grade(s[k],k==='challenge'?3.5:3,k==='transfer').speed?'matches':'needs review'}`);}else lines.push(L('尚未提交','Not submitted'));lines.push(`Hint or explanation opened during this question: ${s.hints.includes(k)}`);}lines.push(L('## 我的反思','## My reflection'),s.reflection,L('## 判讀限制','## Limits'),'Choice checks are deterministic. Free text is preserved verbatim. No AI assessment is performed in this activity. No overall mastery score. Transfer follows prior learning and possible assistance.');if(s.voiceRecords?.length){lines.push('## Voice rehearsal notes (latest 20; typed and confirmed by the learner)',...s.voiceRecords.map(r=>`Stage ${r.context.stage+1}, t=${r.context.t}, field=${r.field}\nTyped rehearsal note: ${r.rawTranscript}\nConfirmed wording: ${r.confirmedTranscript}`));}
for(const [kind,r] of Object.entries(s.aiReviews||{}))lines.push(`## Optional AI follow-up / ${kind}`,`Confirmed text: ${r.request.text}\nGraph t=${r.request.t}`,`Quoted words: ${r.review.quote}`,r.review.observation,r.review.question,'Provisional AI interpretation, not a mastery assessment.');
const content=lines.join('\n\n');$('notesText').value=content;const previous=$('notesLink').getAttribute('href');if(previous)URL.revokeObjectURL(previous);$('notesLink').href=URL.createObjectURL(new Blob([content],{type:'text/markdown;charset=utf-8'}));$('notesDialog').showModal();}
const voice=installVoice({language:()=>lang,context:()=>({stage:s.stage,t:s.t,hinted:s.hints.includes(s.stage===3?'transfer':'challenge')}),onConfirmed:record=>{s.voiceRecords=[...(s.voiceRecords||[]),record].slice(-20);save();},onReview:(kind,record)=>{s.aiReviews={...s.aiReviews,[kind]:record};save();}});
$('closeNotes').onclick=()=>$('notesDialog').close();
$('export').onclick=download;$('reset').onclick=()=>$('resetDialog').showModal();$('cancelReset').onclick=()=>$('resetDialog').close();$('confirmReset').onclick=()=>{s=initial();ephemeral={direction:'',speed:''};try{localStorage.removeItem(KEY);lastRaw=null;blocked=false;storageIssue=false;}catch{storageIssue=true;}save();$('resetDialog').close();render();};render();
